#include "fakepsupage.h"

#include <QTimer>
#include <cmath>

#include "ui_fakepsupage.h"   // generated by uic from fakepsupage.ui

FakePsuPage::FakePsuPage(iwp::DeviceModel *model, QWidget *parent)
    : QWidget(parent), m_model(model), ui(std::make_unique<Ui::FakePsuPage>())
{
    ui->setupUi(this);   // creates every widget of the .ui as ui->objectName

    // debounce: send the setpoint only when the user pauses
    m_sendTimer = new QTimer(this);
    m_sendTimer->setSingleShot(true);
    m_sendTimer->setInterval(150);
    connect(m_sendTimer, &QTimer::timeout, this, [this] {
        m_model->sendCommand(QStringLiteral("setpoint"), ui->setpointSpin->value());
    });

    connect(ui->setpointSpin, &QDoubleSpinBox::valueChanged, this, [this](double v) {
        if (m_updating)
            return;
        m_updating = true;
        ui->setpointDial->setValue(int(std::lround(v * 10.0)));
        m_updating = false;
        m_sendTimer->start();
    });
    connect(ui->setpointDial, &QDial::valueChanged, this, [this](int v) {
        if (m_updating)
            return;
        m_updating = true;
        ui->setpointSpin->setValue(v / 10.0);
        m_updating = false;
        m_sendTimer->start();
    });
    connect(ui->outputButton, &QPushButton::clicked, this,
            [this](bool on) { m_model->sendCommand(QStringLiteral("output"), on); });

    connect(m_model, &iwp::DeviceModel::valueChanged, this,
            [this](const QString &key, const QVariant &) { refresh(key); });
    connect(m_model, &iwp::DeviceModel::staleChanged, this,
            [this](const QString &key, bool) { refresh(key); });
    connect(m_model, &iwp::DeviceModel::statusChanged, this, &FakePsuPage::showStatus);

    for (const QString &key : m_model->keys())
        refresh(key);
    showStatus(m_model->status(), m_model->statusMessage());
}

FakePsuPage::~FakePsuPage() = default;   // here Ui::FakePsuPage is a complete type

void FakePsuPage::refresh(const QString &key)
{
    const QVariant v = m_model->value(key);
    const bool stale = m_model->isStale(key);

    if (key == QLatin1String("idn")) {
        ui->idnLabel->setText(v.toString());
    } else if (key == QLatin1String("volt_meas")) {
        ui->voltLcd->display(v.toDouble());
        ui->voltLcd->setEnabled(!stale);
    } else if (key == QLatin1String("temp")) {
        ui->tempLabel->setText(QString::number(v.toDouble(), 'f', 1));
        ui->tempLabel->setEnabled(!stale);
    } else if (key == QLatin1String("setpoint")) {
        // do not fight the user while they are turning the knob
        if (!m_sendTimer->isActive() && !ui->setpointSpin->hasFocus()) {
            m_updating = true;
            ui->setpointSpin->setValue(v.toDouble());
            ui->setpointDial->setValue(int(std::lround(v.toDouble() * 10.0)));
            m_updating = false;
        }
    } else if (key == QLatin1String("output")) {
        ui->outputButton->setChecked(v.toBool());
    }
}

void FakePsuPage::showStatus(iwp::DeviceModel::Status status, const QString &message)
{
    static const char *names[] = {QT_TR_NOOP("Stopped"), QT_TR_NOOP("Connecting"),
                                  QT_TR_NOOP("Starting"), QT_TR_NOOP("Running"),
                                  QT_TR_NOOP("Offline"), QT_TR_NOOP("Error")};
    const bool running = status == iwp::DeviceModel::Status::Running;
    ui->statusLabel->setText(tr(names[int(status)])
                             + (message.isEmpty() ? QString() : QStringLiteral(" - ") + message));
    ui->statusLabel->setStyleSheet(running ? QStringLiteral("color: #2e7d32;")
                                           : QStringLiteral("color: #c62828;"));
    ui->setpointSpin->setEnabled(running);
    ui->setpointDial->setEnabled(running);
    ui->outputButton->setEnabled(running);
}
